<?php session_start(); if(!isset($_SESSION['id'])||$_SESSION['role']!=='admin'){header('Location:dashboard.php');exit;} include 'db.php';$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id){header('Location:view_books.php');exit;}$s=$conn->prepare('SELECT * FROM books WHERE id=?');$s->bind_param('i',$id);$s->execute();$r=$s->get_result();$row=$r->fetch_assoc();$s->close();if(!$row){header('Location:view_books.php');exit;}$exists=isset($_GET['exists']);$invalid=isset($_GET['invalid']); ?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Edit Book | BookNest</title><link rel="stylesheet" href="style.css"></head><body class="app-body"><header class="topbar"><a class="top-brand" href="dashboard.php">📚 BookNest <small>Library</small></a><div class="user-chip">🛡️ <?= htmlspecialchars($_SESSION['name']) ?> <span class="role-pill">Admin</span></div></header><main class="form-page"><div class="form-head"><div><div class="eyebrow">ADMINISTRATION</div><h1>✏️ Edit Book</h1><p>Update the selected book details.</p></div><a class="secondary-btn" href="view_books.php">← Back to Books</a></div><div class="book-form-card"><?php if($exists): ?><div class="alert error">❌ That ISBN is already used by another book.</div><?php elseif($invalid): ?><div class="alert error">❌ Please enter valid details.</div><?php endif; ?><form action="update_book.php" method="POST"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><div class="form-grid"><div class="field"><label>Book Name</label><input name="book_name" value="<?= htmlspecialchars($row['book_name']) ?>" required></div><div class="field"><label>Author Name</label><input name="author" value="<?= htmlspecialchars($row['author']) ?>" required></div><div class="field"><label>Category</label><input name="category" value="<?= htmlspecialchars($row['category']) ?>" required></div><div class="field"><label>ISBN Number</label><input name="isbn" value="<?= htmlspecialchars($row['isbn']) ?>" required></div><div class="field"><label>Quantity</label><input name="quantity" type="number" min="1" value="<?= (int)$row['quantity'] ?>" required></div></div><button class="primary-btn" type="submit">💾 Save Changes</button></form></div></main></body></html>
